import{bV as a,aL as t,u as n,G as i}from"./chunks/framework.BfzMay2U.js";const u=JSON.parse('{"title":"Java Web 网络基础问答（XML、HTTP、服务器）","description":"","frontmatter":{"title":"Java Web 网络基础问答（XML、HTTP、服务器）","date":"2026-07-25T00:00:00.000Z","categories":["Java"],"tags":["xml","http","web","interview"]},"headers":[],"relativePath":"java/java-net.md","filePath":"java/java-net.md"}'),l={name:"java/java-net.md"};function e(p,s,o,r,h,d){return t(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="java-web-网络基础问答" tabindex="-1">Java Web 网络基础问答 <a class="header-anchor" href="#java-web-网络基础问答" aria-label="Permalink to &quot;Java Web 网络基础问答&quot;">​</a></h1><blockquote><p>整理 Web 基础中的高频面试题：XML 与 HTML 的区别、XML 约束、HTTP 协议、请求响应结构、GET/POST 如何选择、服务器的组成。每题先给出<strong>面试标准回答</strong>，再用<strong>人话</strong>解释一遍，方便理解记忆。</p></blockquote><h2 id="_1-xml-和-html-有什么区别" tabindex="-1">1. XML 和 HTML 有什么区别？ <a class="header-anchor" href="#_1-xml-和-html-有什么区别" aria-label="Permalink to &quot;1. XML 和 HTML 有什么区别？&quot;">​</a></h2><p><strong>面试回答：</strong></p><p>HTML（超文本标记语言）和 XML（可扩展标记语言）的核心区别在于设计目的不同：</p><ul><li><strong>HTML</strong>：标签是预定义、固定的（如 <code>&lt;div&gt;</code>、<code>&lt;p&gt;</code>、<code>&lt;table&gt;</code>），语义是&quot;如何展示&quot;，浏览器负责把标签渲染成页面效果。</li><li><strong>XML</strong>：标签可以自定义，语义是&quot;如何描述数据&quot;，常用于配置文件存储和系统间数据传输（在 JSON 普及之前是主流的数据交换格式）。</li><li><strong>语法严格度不同</strong>：XML 文档必须有且只有一个根标签，标签必须正确嵌套、成对闭合，文件头部要有 <code>&lt;?xml version=&quot;1.0&quot;?&gt;</code> 声明；HTML（尤其 HTML5）语法宽松得多，浏览器会自动纠错容错。</li></ul><p>一句话总结：<strong>HTML 关注展示，XML 关注数据结构</strong>。两者都是标记语言，区别在于标签是否固定、用途是展示还是携带数据。</p><blockquote><p>补充纠正：常见说法&quot;HTML = XML + DTD&quot;并不准确。HTML 源自 SGML，和 XML 是平行发展的两套标记语言标准；真正&quot;用 XML 语法规则重写 HTML&quot;的产物叫 <strong>XHTML</strong>，它才是 HTML 与 XML 语法结合的结果。</p></blockquote><p><strong>人话解释：</strong></p><p>HTML 就像一套装修图纸的固定模板，墙、门、窗户的画法都是定死的，浏览器一看就知道怎么画出页面。XML 是一张空白图纸，标签含义你自己定义，比较适合用来存数据、或者在不同系统之间传数据（后来这个活儿基本被更轻量的 JSON 抢走了）。</p><h2 id="_2-xml-约束有什么作用-约束类型和引入方式" tabindex="-1">2. XML 约束有什么作用？约束类型和引入方式？ <a class="header-anchor" href="#_2-xml-约束有什么作用-约束类型和引入方式" aria-label="Permalink to &quot;2. XML 约束有什么作用？约束类型和引入方式？&quot;">​</a></h2><p><strong>面试回答：</strong></p><p>XML 标签可以自定义，如果没有任何限制，同一份数据每个人都能写出不同的标签结构，无法互相解析。<strong>XML 约束</strong>就是用来规定一份 XML 文档&quot;允许出现哪些标签、标签的顺序、属性、内容格式&quot;，作用有三点：</p><ol><li>限制标签的书写规则，防止乱写</li><li>开发工具能据此提供自动补全和校验提示</li><li>不同系统之间约定好格式后，配置传递更可靠</li></ol><p><strong>约束分为两类：DTD 和 Schema（XSD）。</strong></p><ul><li><p><strong>DTD（文档类型定义）</strong>：语法简单，但不支持数据类型校验，无命名空间机制，引入方式：</p><div class="language-xml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;?</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">xml</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">?&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;!DOCTYPE 根标签 SYSTEM &quot;xx.dtd&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">根标签</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;...&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">根标签</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li><li><p><strong>Schema（XSD）</strong>：本身也是一份 XML 文档，支持数据类型、命名空间，是 DTD 的替代方案，引入方式：</p><div class="language-xml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;?</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">xml</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">?&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">根标签</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    xmlns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;默认命名空间&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    xmlns:别名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;其他命名空间&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    xmlns:xsi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://www.w3.org/2001/XMLSchema-instance&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    xsi:schemaLocation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;命名空间1 xxx1.xsd 命名空间2 xxx2.xsd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">标签名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 属于默认命名空间 xmlns --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">别名:标签名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 属于别名对应的命名空间 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">根标签</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div></li></ul><p><strong>人话解释：</strong></p><p>约束就是给 XML 定&quot;格式规范&quot;，好比公司统一的合同模板：字段名、顺序、类型都提前约定好，别人不能随便乱填。DTD 是老式的简单模板，只能限制标签结构；Schema 是升级版，还能限制数据类型（比如某个字段必须是数字），并支持&quot;命名空间&quot;来区分不同来源的标签（类似 Java 里用包名 <code>com.xxx.User</code> 区分不同包下同名的类）。</p><h2 id="_3-什么是-http-协议-主要有什么作用" tabindex="-1">3. 什么是 HTTP 协议？主要有什么作用？ <a class="header-anchor" href="#_3-什么是-http-协议-主要有什么作用" aria-label="Permalink to &quot;3. 什么是 HTTP 协议？主要有什么作用？&quot;">​</a></h2><p><strong>面试回答：</strong></p><p>HTTP（超文本传输协议）是应用层协议，规定了客户端和服务器之间<strong>请求与响应的数据格式</strong>。它底层依赖 <strong>TCP/IP</strong> 提供可靠的字节流传输：</p><ul><li>建立连接时经历 TCP <strong>三次握手</strong>（SYN → SYN+ACK → ACK）</li><li>断开连接时经历 TCP <strong>四次挥手</strong>（FIN/ACK 交换，因为 TCP 是全双工，两个方向要分别关闭）</li></ul><p>HTTP 本身是<strong>无状态、基于请求-响应模型</strong>的协议：客户端发起一次请求，服务器返回一次响应，双方不会主动记住上一次交互的状态（这也是后来需要 Cookie/Session/Token 来维持状态的原因）。目前主流版本是 HTTP/1.1（默认长连接）、HTTP/2（多路复用）、HTTP/3（基于 UDP 的 QUIC）。</p><p><strong>人话解释：</strong></p><p>HTTP 就是浏览器和服务器&quot;打电话&quot;时用的通话格式规范：先约定好怎么开头、怎么说重点、怎么挂电话。这次通话本身依赖 TCP 这条稳定的&quot;电话线&quot;（三次握手相当于打电话前先确认&quot;你能听到我吗&quot;&quot;能&quot;&quot;那我们开始说&quot;；四次挥手是挂电话时双方都说一次&quot;没有话要说了&quot;才真正挂断）。HTTP &quot;无状态&quot;指的是：这次通话挂了之后，下次再打电话，对方完全不记得你是谁，除非你主动带上&quot;身份证&quot;（Cookie/Token）。</p><h2 id="_4-请求和响应数据包的结构是什么" tabindex="-1">4. 请求和响应数据包的结构是什么？ <a class="header-anchor" href="#_4-请求和响应数据包的结构是什么" aria-label="Permalink to &quot;4. 请求和响应数据包的结构是什么？&quot;">​</a></h2><p><strong>面试回答：</strong></p><p><strong>请求（Request）报文结构：</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求行   GET /index.html HTTP/1.1</span></span>
<span class="line"><span>请求头   Host: example.com</span></span>
<span class="line"><span>         User-Agent: ...</span></span>
<span class="line"><span>         Content-Type: application/json</span></span>
<span class="line"><span>请求空行  (CRLF，标志头部结束)</span></span>
<span class="line"><span>请求体   {&quot;key&quot;: &quot;value&quot;}   （GET 一般没有请求体）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>响应（Response）报文结构：</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>状态行   HTTP/1.1 200 OK</span></span>
<span class="line"><span>响应头   Content-Type: text/html</span></span>
<span class="line"><span>         Content-Length: 1234</span></span>
<span class="line"><span>响应空行  (CRLF)</span></span>
<span class="line"><span>响应体   &lt;html&gt;...&lt;/html&gt;   （实际返回的数据，字节流）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>要点：请求行三部分是<strong>方法、URL、协议版本</strong>；状态行三部分是<strong>协议版本、状态码、状态描述</strong>；头部和主体之间<strong>必须有一个空行</strong>分隔，这是 HTTP 报文解析的关键分界点。</p><p><strong>人话解释：</strong></p><p>请求报文就像寄快递的运单：第一行写清楚&quot;寄什么方式、寄到哪、用哪个协议&quot;（请求行），中间贴一堆标签写备注信息（请求头），空一行后面才是真正要寄的东西（请求体）。响应报文是收件人回你的单子：第一行告诉你&quot;处理结果是成功还是失败&quot;（状态行 200/404/500），后面同样是备注信息加实际内容。这个&quot;空行&quot;很关键，程序解析报文时就是靠这个空行来判断&quot;头部读完了，接下来是正文&quot;。</p><h2 id="_5-get-和-post-有什么区别-如何选择" tabindex="-1">5. GET 和 POST 有什么区别？如何选择？ <a class="header-anchor" href="#_5-get-和-post-有什么区别-如何选择" aria-label="Permalink to &quot;5. GET 和 POST 有什么区别？如何选择？&quot;">​</a></h2><p><strong>面试回答：</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>GET</th><th>POST</th></tr></thead><tbody><tr><td>语义</td><td>获取资源</td><td>提交/创建资源</td></tr><tr><td>参数位置</td><td>拼接在 URL 后（<code>?key=value</code>），无请求体</td><td>放在请求体中</td></tr><tr><td>数据大小</td><td>受 URL 长度限制（浏览器/服务器通常限制在几 KB）</td><td>理论上无限制</td></tr><tr><td>安全性</td><td>参数暴露在 URL、浏览器历史、日志中</td><td>相对不暴露在 URL，但仍非加密，需配合 HTTPS</td></tr><tr><td>幂等性</td><td>幂等（多次请求结果一致），可被浏览器缓存</td><td>非幂等，不会被缓存</td></tr></tbody></table><p><strong>选择原则：</strong> 优先用 GET；当出现以下情况之一时改用 POST：</p><ol><li>传递的数据量较大（一般以 2KB 作为经验分界线）</li><li>传递敏感/隐私数据（如密码）</li><li>是新增、修改等有副作用的操作（不满足幂等语义）</li></ol><p><strong>人话解释：</strong></p><p>GET 相当于&quot;我要看看这个东西&quot;，参数写在网址栏里，谁都能看到（就像把收货地址写在快递盒外面），而且浏览器会记住这次请求方便你重复访问或缓存。POST 相当于&quot;我要交个东西给你&quot;，内容装在包裹内部（请求体），网址栏看不到，适合传密码、传大文件、或者传&quot;会改变服务器数据&quot;的操作（比如注册、下单）。经验法则：能用 GET 就用 GET，涉密或数据量大就换 POST。</p><h2 id="_6-什么是服务器-服务器由哪三部分组成" tabindex="-1">6. 什么是服务器？服务器由哪三部分组成？ <a class="header-anchor" href="#_6-什么是服务器-服务器由哪三部分组成" aria-label="Permalink to &quot;6. 什么是服务器？服务器由哪三部分组成？&quot;">​</a></h2><p><strong>面试回答：</strong></p><p>在一个 Web 项目中，架构分为**客户端（Client）<strong>和</strong>服务端（Server）**两侧：</p><ul><li><strong>客户端</strong>：负责界面展示和用户交互，形式多样 —— 浏览器（HTML/CSS/JS + 前端工程化：Vue/Node/npm/Axios/Pinia/Element Plus）、Android App、iOS App、微信/支付宝小程序、甚至现在的 AI 智能体客户端。</li><li><strong>服务端（服务器）</strong>：负责业务逻辑处理，返回数据给客户端（通常以 JSON 格式传输）。</li></ul><p><strong>服务器由三部分组成：</strong></p><ol><li><strong>服务器主机</strong>：物理机或云主机，提供硬件资源（CPU、内存、磁盘、网络）</li><li><strong>服务器软件</strong>：能够接收 HTTP 请求并响应的软件环境，如 Tomcat、Nginx、Jetty</li><li><strong>Web 项目</strong>：部署在服务器软件上的具体业务应用（如一个 Spring Boot 打的 jar 包）</li></ol><p>三者关系：主机提供硬件能力 → 软件提供协议解析和请求调度能力 → Web 项目实现具体业务逻辑，三者叠加才能对外提供完整的 Web 服务。</p><p><strong>人话解释：</strong></p><p>做一个 Web 系统分两块：客户端负责&quot;给用户看&quot;，服务端负责&quot;处理逻辑、存数据&quot;，两边通过 JSON 传数据。而&quot;服务器&quot;这个词其实是三层叠加的：最底下是一台电脑（主机），电脑上装了一个能听懂 HTTP 请求的软件（比如 Tomcat，相当于翻译官），软件上再跑着你写的具体项目代码（比如一个电商系统）。所以说&quot;服务器&quot;，既可以指那台机器，也可以指跑在机器上的软件，要看上下文。</p>`,50)])])}const k=a(l,[["render",e]]);export{u as __pageData,k as default};
